<template><div class="project-media"><figure v-for="file in media" :key="file.id" :class="{'media-video':file.kind==='video','media-cover':file.kind==='cover'}"><template v-if="file.kind==='video'"><video v-if="urls[file.id]" :src="urls[file.id]" controls preload="metadata" playsinline /><button v-else class="secondary-button" :disabled="loading[file.id]" @click="load(file)">{{ $ui(loading[file.id]?'正在加载视频…':'加载视频预览') }}</button></template><img v-else-if="urls[file.id]" :src="urls[file.id]" :alt="file.filename" loading="lazy" /><p v-else role="status">{{ $ui('正在读取…') }}</p><figcaption>{{ $ui(file.kind==='cover'?'封面图':file.kind==='video'?'介绍视频':'画廊图片') }} · {{ file.filename }}</figcaption><p v-if="errors[file.id]" role="alert" class="form-error">{{ $ui(errors[file.id]) }}</p><slot :file="file" /></figure></div></template>
<script setup lang="ts">
import {reactive,watch,onBeforeUnmount}from'vue';import{store,type ProjectMedia}from'@/api/store';const props=defineProps<{media:ProjectMedia[]}>(),urls=reactive<Record<string,string>>({}),errors=reactive<Record<string,string>>({}),loading=reactive<Record<string,boolean>>({});let active=true;
async function load(file:ProjectMedia){if(loading[file.id]||urls[file.id])return;loading[file.id]=true;errors[file.id]='';try{const value=await store.mediaBlob(file.id);if(active&&props.media.some(m=>m.id===file.id))urls[file.id]=URL.createObjectURL(value.blob);}catch(e){if(active)errors[file.id]=e instanceof Error?e.message:'媒体暂不可用';}finally{if(active)loading[file.id]=false;}}
watch(()=>props.media.map(m=>m.id).join(','),()=>{for(const id of Object.keys(urls))if(!props.media.some(m=>m.id===id)){URL.revokeObjectURL(urls[id]);delete urls[id];}for(const file of props.media)if(file.kind!=='video')void load(file);},{immediate:true});onBeforeUnmount(()=>{active=false;for(const url of Object.values(urls))URL.revokeObjectURL(url);});
</script>
<style scoped>.project-media{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px;margin:20px 0}.project-media figure{margin:0;border:1px solid var(--market-border);padding:12px;border-radius:12px;min-width:0}.project-media img,.project-media video{display:block;width:100%;max-height:400px;object-fit:contain;border-radius:8px;background:var(--market-surface-soft)}.project-media .media-cover,.project-media .media-video{grid-column:1/-1}.project-media figcaption{font-size:12px;color:var(--market-muted);margin-top:10px;overflow-wrap:anywhere}</style>
